static const char kk_dgc_mesh_shader[] = "/* Apple9 Mesh ICB commands consume the existing Mesh slot5 layouts. */\nstruct MeshState {\n   Params p;\n   ulong mesh[KK_DGC_MESH_WORDS];\n   uint metadata_offset, slices, group_limit;\n   packed_uint3 object_local, mesh_local;\n};\nstatic_assert(sizeof(MeshState) == KK_DGC_MESH_STATE_SIZE, \"Mesh DGC parameter ABI\");\nkernel void kk_dgc_mesh_commands(constant MeshState &s [[buffer(KK_ARGUMENT_ROOT)]],\n   constant ICB &icb [[buffer(KK_ARGUMENT_SAMPLERS)]], uint i [[thread_position_in_grid]]) {\n   constant Params &p = s.p;\n   if (i >= p.maximum) return;\n   uint count = p.count ? min(*(const device uint *)p.count, p.maximum + p.first) : p.maximum + p.first;\n   if (p.condition && ((*(const device uint *)p.condition != 0) == bool(p.inverted))) count = 0;\n   uint active = count > p.first ? min(count - p.first, p.maximum) : 0;\n   if (i == 0) {\n      device uint *range = (device uint *)p.execution_range;\n      range[0] = 0; range[1] = active * s.slices;\n   }\n   if (i >= active) return;\n   kk_dgc_expand_sequence(p, i, true);\n   device uchar *record = (device uchar *)p.output + ulong(i) * p.record_stride;\n   const device uint *args = (const device uint *)(record + p.args_offset);\n   device uchar *root = p.root_size ? record : (device uchar *)p.base_root;\n   bool valid = args[0] && args[1] && args[2] &&\n      args[0] <= KK_DGC_MESH_DIMENSION && args[1] <= KK_DGC_MESH_DIMENSION && args[2] <= KK_DGC_MESH_DIMENSION;\n   ulong total = valid ? ulong(args[0]) * args[1] * args[2] : 0;\n   valid &= total <= KK_DGC_MESH_MAX_GROUPS;\n   for (uint slice = 0; slice < s.slices; ++slice) {\n      render_command cmd(icb.commands, i * s.slices + slice);\n      cmd.reset();\n      uint base = slice * s.group_limit;\n      if (!valid || base >= total) continue;\n      device uchar *metadata = record + s.metadata_offset + slice * KK_DGC_MESH_METADATA_STRIDE;\n      for (uint word = 0; word < KK_DGC_MESH_WORDS; ++word)\n         ((device ulong *)metadata)[word] = s.mesh[word];\n      device uchar *batch = metadata + KK_DGC_MESH_PARAMETER_SIZE;\n      for (uint word = 0; word < KK_DGC_MESH_BATCH_SIZE / 4; ++word)\n         ((device uint *)batch)[word] = 0;\n      device uint *original = (device uint *)(batch + KK_DGC_MESH_INPUT_GRID);\n      original[0] = args[0]; original[1] = args[1]; original[2] = args[2];\n      *(device ulong *)(metadata + KK_DGC_MESH_BATCH) = ulong(batch);\n      *(device ulong *)(metadata + KK_DGC_MESH_INDIRECT_GRID) = ulong(args);\n      *(device ulong *)(metadata + KK_DGC_MESH_INDIRECT_COUNT) = 0;\n      *(device ulong *)(metadata + KK_DGC_MESH_PREDICATE) = 0;\n      *(device uint *)(metadata + KK_DGC_MESH_DRAW_ID) = 0;\n      *(device uint *)(metadata + KK_DGC_MESH_MAX_DRAW_COUNT) = 1;\n      uint groups = min(uint(total) - base, s.group_limit);\n      *(device uint *)(metadata + KK_DGC_MESH_TASK_BASE) = base;\n      *(device uint *)(metadata + KK_DGC_MESH_PAYLOAD_STRIDE) = groups;\n      uint width = min(groups, uint(KK_DGC_MESH_DIMENSION));\n      uint3 grid = uint3(width, (groups + width - 1) / width, 1);\n      device uint *dispatch = (device uint *)(batch + KK_DGC_MESH_DISPATCH);\n      dispatch[0] = grid.x; dispatch[1] = grid.y; dispatch[2] = grid.z;\n      *(device uint *)(batch + KK_DGC_MESH_COUNT) = groups;\n      cmd.set_object_buffer(root, KK_ARGUMENT_ROOT); cmd.set_mesh_buffer(root, KK_ARGUMENT_ROOT); cmd.set_fragment_buffer(root, KK_ARGUMENT_ROOT);\n      cmd.set_object_buffer((device void *)p.samplers, KK_ARGUMENT_SAMPLERS); cmd.set_mesh_buffer((device void *)p.samplers, KK_ARGUMENT_SAMPLERS); cmd.set_fragment_buffer((device void *)p.samplers, KK_ARGUMENT_SAMPLERS);\n      cmd.set_object_buffer(record + p.draw_offset, KK_ARGUMENT_PER_DRAW); cmd.set_mesh_buffer(record + p.draw_offset, KK_ARGUMENT_PER_DRAW); cmd.set_fragment_buffer(record + p.draw_offset, KK_ARGUMENT_PER_DRAW);\n      cmd.set_object_buffer(metadata, KK_ARGUMENT_MESH_PARAMETERS); cmd.set_mesh_buffer(metadata, KK_ARGUMENT_MESH_PARAMETERS); cmd.set_fragment_buffer(metadata, KK_ARGUMENT_MESH_PARAMETERS);\n      cmd.set_object_buffer((device void *)0, KK_ARGUMENT_POLY_LAYER_REPLAY); cmd.set_mesh_buffer((device void *)0, KK_ARGUMENT_POLY_LAYER_REPLAY); cmd.set_fragment_buffer((device void *)0, KK_ARGUMENT_POLY_LAYER_REPLAY);\n      if (p.linked_vs_buffer) {\n         cmd.set_object_buffer((device void *)p.linked_vs_buffer, KK_ARGUMENT_VS_VFT_WRAPPER);\n         cmd.set_mesh_buffer((device void *)p.linked_vs_buffer, KK_ARGUMENT_VS_VFT_WRAPPER);\n      }\n      if (p.linked_fs_buffer) cmd.set_fragment_buffer((device void *)p.linked_fs_buffer, KK_ARGUMENT_FS_VFT_WRAPPER);\n      if (p.interlock_guard) cmd.set_fragment_buffer((device void *)p.interlock_guard, KK_ARGUMENT_INTERLOCK_GUARD);\n      cmd.draw_mesh_threadgroups(grid, uint3(s.object_local), uint3(s.mesh_local));\n   }\n}\n";
